// ─── File: ShardTxnDemo.java ───
// Runnable demo: cheap single-shard read, expensive scatter-gather, cross-shard saga.
package com.bank.shardtxn;

import java.math.BigDecimal;
import java.util.logging.*;

public class ShardTxnDemo {

    private static final Logger log = Logger.getLogger("ShardTxn");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ShardRouter router = new ShardRouter(4);
        // Rajesh's two accounts co-located on his shard (keyed by customer "rajesh").
        router.seed("rajesh", "SAV2001", new BigDecimal("1000000"));
        router.seed("rajesh", "SAV2002", new BigDecimal("200000"));
        router.seed("priya", "CUR3001", new BigDecimal("250000"));

        // 1) CHEAP single-shard query: find Rajesh's accounts → one node.
        log.info(() -> "single-shard read (rajesh) = " + router.readCustomer("rajesh")
                + "  ← cheap, one node");

        // 2) EXPENSIVE scatter-gather: total accounts across ALL shards.
        log.warning("scatter-gather: querying EVERY shard to count all accounts...");
        log.info(() -> "global account count = " + router.scatterGatherCount()
                + "  ← fans out to all shards, waits for slowest");

        // 3) LOCAL ACID transfer between Rajesh's own two accounts (same shard).
        boolean local = router.localTransfer("rajesh", "SAV2001", "SAV2002", new BigDecimal("50000"));
        log.info(() -> "same-shard transfer committed locally (ACID) = " + local);

        // 4) CROSS-SHARD transfer rajesh → priya via SAGA (debit + credit + compensate).
        CrossShardTransferSaga saga = new CrossShardTransferSaga(router);
        saga.transfer("rajesh", "SAV2001", "priya", "CUR3001", new BigDecimal("50000"), false);

        // 5) CROSS-SHARD transfer that FAILS on credit → compensating refund runs.
        saga.transfer("rajesh", "SAV2001", "priya", "CUR3001", new BigDecimal("50000"), true);
    }
}

// ─── node/Shard.java (independent DB; local ACID only within itself) ───
class Shard {
    final int id;
    final java.util.Map<String, BigDecimal> accounts = new java.util.HashMap<>();
    final java.util.Map<String, String> ownerOf = new java.util.HashMap<>();
    Shard(int id) { this.id = id; }
    // A LOCAL transaction — atomic within this one node.
    synchronized void debit(String acct, BigDecimal amt) {
        BigDecimal bal = accounts.get(acct);
        if (bal.compareTo(amt) < 0) throw new RuntimeException("insufficient funds");
        accounts.put(acct, bal.subtract(amt));
    }
    synchronized void credit(String acct, BigDecimal amt) {
        accounts.put(acct, accounts.getOrDefault(acct, BigDecimal.ZERO).add(amt));
    }
    int count() { return accounts.size(); }
}

// ─── router/ShardRouter.java (routes by customer; single-shard vs scatter-gather) ───
class ShardRouter {
    private final java.util.List<Shard> shards = new java.util.ArrayList<>();
    ShardRouter(int n) { for (int i = 0; i < n; i++) shards.add(new Shard(i)); }
    Shard shardFor(String customerId) {
        return shards.get(Math.floorMod(customerId.hashCode(), shards.size()));
    }
    void seed(String customer, String acct, BigDecimal bal) {
        Shard s = shardFor(customer); s.accounts.put(acct, bal); s.ownerOf.put(acct, customer);
    }
    String readCustomer(String customer) {           // SINGLE shard — cheap
        Shard s = shardFor(customer);
        return s.accounts.entrySet().stream()
                .filter(e -> customer.equals(s.ownerOf.get(e.getKey())))
                .map(e -> e.getKey() + "=" + e.getValue()).toList().toString();
    }
    int scatterGatherCount() {                        // ALL shards — expensive
        return shards.stream().mapToInt(Shard::count).sum();
    }
    boolean localTransfer(String customer, String from, String to, BigDecimal amt) {
        Shard s = shardFor(customer);                 // both accounts on the SAME shard
        s.debit(from, amt); s.credit(to, amt);        // local ACID
        return true;
    }
    Shard shardOf(String customer) { return shardFor(customer); }
}

// ─── txn/CrossShardTransferSaga.java (debit shard A, credit shard B, compensate on failure) ───
class CrossShardTransferSaga {
    private static final Logger log = Logger.getLogger("ShardTxn");
    private final ShardRouter router;
    CrossShardTransferSaga(ShardRouter router) { this.router = router; }

    void transfer(String fromCust, String fromAcct, String toCust, String toAcct,
                  BigDecimal amt, boolean simulateCreditFailure) {
        Shard a = router.shardOf(fromCust), b = router.shardOf(toCust);
        a.debit(fromAcct, amt);                       // step 1 local txn (shard A)
        log.info(() -> "SAGA step1: debited " + amt + " from " + fromAcct + " (shard " + a.id + ")");
        try {
            if (simulateCreditFailure) throw new RuntimeException("shard B credit failed");
            b.credit(toAcct, amt);                    // step 2 local txn (shard B)
            log.info(() -> "SAGA step2: credited " + amt + " to " + toAcct + " (shard " + b.id + ")");
            log.info("SAGA committed (no single-node ACID across shards; two local txns)");
        } catch (RuntimeException e) {
            a.credit(fromAcct, amt);                  // COMPENSATION: refund shard A
            log.severe("SAGA step2 FAILED → compensating refund to " + fromAcct
                    + " (saga rolled back, intermediate state was briefly visible)");
        }
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
